import time

def cache(ttl):
    def decorator(func):
        cache = {}

        def wrapper(*args, **kwargs):
            # Generate a hashable key from arguments
            key = (args, tuple(sorted(kwargs.items())))
            current_time = time.time()

            if key in cache:
                stored_time, result = cache[key]
                if current_time - stored_time < ttl:
                    return result

            # Compute the result
            result = func(*args, **kwargs)
            # Store the result with the current timestamp
            cache[key] = (current_time, result)
            return result

        return wrapper

    return decorator

@cache(ttl=300)
def expensive_function(arg1, arg2):
    # Simulate an expensive computation
    time.sleep(2)  # Simulate delay
    return arg1 * arg2

def get_env_value(key, default, env_path='.env'):
    """
    Retrieve a value from a .env file, with a default fallback.

    Args:
        key (str): The key to look up in the .env file.
        default (str): The default value to return if the key is not found.
        env_path (str, optional): Path to the .env file. Defaults to '.env'.

    Returns:
        str: The value from the .env file or the default if not found.
    """
    try:
        with open(env_path, 'r') as f:
            env_vars = {}
            for line in f:
                line = line.strip()
                if not line or line.startswith('#'):
                    continue
                if '=' in line:
                    k, v = line.split('=', 1)
                    env_vars[k.strip()] = v.strip()
        return env_vars.get(key, default)
    except FileNotFoundError:
        return default
